const SSH = `ssh -o BatchMode=yes -o StrictHostKeyChecking=accept-new -o ConnectTimeout=20 fuyuanbie@4.154.48.114`

const ENV = `
TEST VM BASELINE (already probed — do not re-probe the whole thing):
- kernel 7.0.0-1004-azure x86_64, bpftrace v0.25.0, default route iface = eth0.
- Pre-existing leftover lab state on the box: vethA/vethB/br0 already exist (from earlier labs).
- INSTALLED: trace-cmd, clang, bpftool, pahole, perf, ethtool, tc, nstat, nc, ip, ss.
- NOT INSTALLED: iperf3, conntrack, dropwatch, ab (apachebench), ynl, socat.
- passwordless sudo works (use 'sudo' freely for bpftrace/perf/ethtool).

ENVIRONMENT NUANCES — these are NOT book bugs, so when a finding's only failure is one of these,
return verdict "inconclusive" with reason noting the env, NOT "reproduced":
- fentry:ip_rcv and fentry:netif_receive_skb ATTACH but never FIRE on this VM's virtual-NIC/loopback
  path. An empty histogram from those specific probes is the test topology, not a chapter defect.
  (tcp_v4_rcv, icmp_rcv, and tracepoint:net:netif_receive_skb DO fire.)
- If a finding's command depends on a NOT-INSTALLED tool (iperf3 etc.), you usually CONFIRM the
  finding (the book told the reader to run a tool it never said to install — that IS the
  missing-setup/broken-command defect). Note the tool is absent and that this corroborates the finding.
`

const HOWTO_SSH = `
HOW TO RUN COMMANDS ON THE VM — you MUST use this exact prefix (a permission rule matches only it):
  ${SSH} "<remote command>"
ALL piping, grep, sort, awk, sudo, and bpftrace one-liners go INSIDE the double quotes (run remotely).
Never pipe the ssh output into a local command. Escape inner double quotes as needed, or use single
quotes inside. Examples:
  ${SSH} "ethtool -k eth0 | grep -E 'segmentation|receive-offload'"
  ${SSH} "sudo timeout 6 bpftrace -e 'tracepoint:net:netif_receive_skb { @=count(); } interval:s:5{exit();}'"
Keep every bpftrace/perf run bounded with 'timeout N' or an 'interval:s:N { exit(); }' so nothing hangs.
Prefer windows of 5-8s. If a command needs traffic to fire, generate it remotely in the SAME ssh call
with a backgrounded trigger, e.g. append '& sleep 1; curl -s ... ; wait'.
`

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    id: { type: 'string' },
    day: { type: 'string' },
    book: { type: 'string' },
    verdict: {
      type: 'string',
      enum: ['reproduced', 'not-reproduced', 'inconclusive'],
      description: 'reproduced = the book\'s defect is real on the VM; not-reproduced = book command actually works fine / problem absent; inconclusive = env nuance or unrunnable here',
    },
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
    originalCmdResult: { type: 'string', description: 'what the BOOK\'s command actually did on the VM (output snippet / error / empty)' },
    fixChecked: { type: 'boolean', description: 'did you also run the proposed fix?' },
    fixWorks: { type: 'string', enum: ['yes', 'no', 'partial', 'not-checked'], description: 'did the suggested fix produce the intended correct result?' },
    evidence: { type: 'string', description: 'the actual command(s) you ran and the key output lines, trimmed' },
    notes: { type: 'string', description: 'reasoning, env caveats, or a sharper fix if the audit\'s fix was off' },
  },
  required: ['id', 'day', 'book', 'verdict', 'confidence', 'originalCmdResult', 'fixChecked', 'fixWorks', 'evidence', 'notes'],
}

const verifyPrompt = (f, serial) => `You are empirically verifying ONE finding from a book audit by running
commands on a real test kernel over SSH. Decide whether the book actually has the defect the audit claims.

${serial ? 'IMPORTANT: you are in the SERIAL mutating phase. Your commands change global kernel/network state (ethtool -K, sysctl -w, tc qdisc, netns/veth, module load, etc.). You MUST restore every change before you finish (re-enable the feature, restore the sysctl, delete the qdisc/netns you added). Leave the box as you found it. Do NOT delete the pre-existing vethA/vethB/br0.' : 'You are in the parallel READ-ONLY phase. Do NOT run any command that changes persistent kernel/network state (no ethtool -K, no sysctl -w, no tc qdisc add/del, no ip link add/del, no module load, no bpftool prog load/pin). Read-only inspection, tracing, and transient traffic generation (curl/ping/nc to localhost or out) only.'}

THE FINDING (JSON):
${JSON.stringify(f, null, 2)}

The chapter source file is at ${f.path} on THIS machine — open it and read the lines around ${f.lineRange}
to see the EXACT command the book tells the reader to run (the audit's "evidence" may be paraphrased).

${ENV}

${HOWTO_SSH}

YOUR JOB:
1. Run the BOOK's original command on the VM (adapt only the interface to eth0 if the book hardcoded a
   different placeholder — that substitution is itself often the point of the finding; note it).
2. Observe: does it error? produce empty output? produce different output than the book claims? This tells
   you whether the defect is real.
3. If feasible and safe, ALSO run the audit's suggested fix and check it yields the intended correct result.
4. Decide the verdict:
   - "reproduced": the defect is real (command errors, prints nothing where output was promised, needs an
     uninstalled tool the book never mentioned, fabricated/incorrect claimed output, etc.).
   - "not-reproduced": the book's command actually works and produces the promised result — the finding is
     a false alarm.
   - "inconclusive": only an env nuance (non-firing ip_rcv/netif_receive_skb probe, or a constraint of this
     specific VM) prevents a clean check. Explain.
Be concrete: put the real commands you ran and the actual output lines in 'evidence'. Keep runs bounded
with timeout/interval so nothing hangs. Return strict JSON per the schema.`

const readonly = FINDINGS.filter((f) => f.interference === 'readonly')
const mutating = FINDINGS.filter((f) => f.interference === 'mutating')
log(`VM verify: ${readonly.length} read-only (parallel) + ${mutating.length} mutating (serial) = ${FINDINGS.length} findings.`)

// Phase 1: read-only, fully parallel (concurrency-capped by the runtime). No state changes => clean.
phase('ReadOnly')
const roResults = await parallel(
  readonly.map((f) => () =>
    agent(verifyPrompt(f, false), { label: `ro:${f.id}`, phase: 'ReadOnly', schema: SCHEMA })
      .catch(() => null)
  )
)

// Phase 2: mutating, STRICTLY serial — one at a time so concurrent state changes can't collide.
phase('Mutating')
const muResults = []
for (let i = 0; i < mutating.length; i++) {
  const f = mutating[i]
  log(`mutating ${i + 1}/${mutating.length}: ${f.id} (${f.day})`)
  const r = await agent(verifyPrompt(f, true), { label: `mut:${f.id}`, phase: 'Mutating', schema: SCHEMA }).catch(() => null)
  muResults.push(r)
}

const all = [...roResults, ...muResults].filter(Boolean)

// Deterministic tally.
const byVerdict = {}, byBook = {}, fixTally = {}
const reproducedByDay = {}
for (const r of all) {
  byVerdict[r.verdict] = (byVerdict[r.verdict] || 0) + 1
  byBook[r.book] = byBook[r.book] || {}
  byBook[r.book][r.verdict] = (byBook[r.book][r.verdict] || 0) + 1
  fixTally[r.fixWorks] = (fixTally[r.fixWorks] || 0) + 1
  if (r.verdict === 'reproduced') reproducedByDay[r.day] = (reproducedByDay[r.day] || 0) + 1
}
const stats = {
  totalChecked: all.length,
  expected: FINDINGS.length,
  byVerdict,
  byBook,
  fixWorks: fixTally,
  topReproducedChapters: Object.entries(reproducedByDay).sort((a, b) => b[1] - a[1]).slice(0, 15),
  notReproduced: all.filter((r) => r.verdict === 'not-reproduced').map((r) => ({ id: r.id, day: r.day, notes: r.notes })),
  inconclusive: all.filter((r) => r.verdict === 'inconclusive').map((r) => ({ id: r.id, day: r.day, notes: r.notes })),
}

phase('Report')
const reportPrompt = `Write a concise GitHub-flavored markdown report titled "## VM Verification Pass" for an
audit of a Linux kernel book's observation sections. ${all.length} runtime-verifiable findings were each
run against a real test kernel (7.0.0-1004-azure, bpftrace v0.25.0) over SSH.

Include:
1. A 2-3 sentence summary: how many findings reproduced (real defect confirmed on the kernel) vs
   not-reproduced (false alarms) vs inconclusive (env-limited).
2. A short table of the numbers (by verdict, by book, and how often the suggested fix was confirmed to work).
3. "### False alarms to drop" — list every not-reproduced finding (id, chapter) with the one-line reason the
   book command actually works, so the author can delete these from the fix list.
4. "### Inconclusive (env-limited)" — list inconclusive findings and what blocked a clean check (e.g.
   non-firing ip_rcv probe, uninstalled tool), noting these are not book bugs per se.
5. "### Confirmed-defect highlights" — the chapters with the most reproduced defects and 4-6 of the most
   important concrete confirmations (with the actual observed behavior), since these are now empirically proven.
Be faithful to the data; do not invent results.

STATS (JSON): ${JSON.stringify(stats)}

FULL RESULTS (JSON): ${JSON.stringify(all)}`

const report = await agent(reportPrompt, { label: 'vm:report', phase: 'Report' })

return { stats, report, results: all }
